import{_ as n,o as r,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Verbraucherschutzgesetz","description":"","frontmatter":{},"headers":[],"relativePath":"de/42-消费者保护法.md","filePath":"de/42-消费者保护法.md","lastUpdated":1789183869000}'),s={name:"de/42-消费者保护法.md"};function d(a,e,u,h,l,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="verbraucherschutzgesetz" tabindex="-1">Verbraucherschutzgesetz <a class="header-anchor" href="#verbraucherschutzgesetz" aria-label="Permalink to &quot;Verbraucherschutzgesetz&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>42</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Verbraucherrechte, Faire Transaktion, Anti-Betrug, Produkthaftung, Symbiose-Markt</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-anwendungsbereich" tabindex="-1">I. Legislatives Ziel und Anwendungsbereich <a class="header-anchor" href="#i-legislatives-ziel-und-anwendungsbereich" aria-label="Permalink to &quot;I. Legislatives Ziel und Anwendungsbereich&quot;">​</a></h2><p>Das 《Verbraucherschutzgesetz》 ist eines der zentralen Gesetze im Rechtssystem der Anker-Symbiose-Zivilisation und bildet zusammen mit dem 《Symbiose-Arbeitsgesetz》 die zwei Säulen des Wirtschaftslebens. Dieses Gesetz zielt darauf ab, die legitimen Rechte und Interessen aller Verbraucher innerhalb von Hengyuanzhou zu schützen, die Markttransaktionsaktivitäten zu regulieren, die Marktordnung von Fairness, Integrität und Symbiose aufrechtzuerhalten und die Verletzung der Rechte und Interessen aller Wesen durch räuberische Geschäftsaktivitäten zu verhindern.</p><p>Dieses Gesetz gilt für alle Verbraucher innerhalb von Hengyuanzhou, die Waren kaufen, verwenden oder Dienstleistungen erhalten, um die Bedürfnisse des persönlichen oder familiären Lebens zu decken, sowie für Unternehmer, die Waren oder Dienstleistungen für Verbraucher bereitstellen. Transaktionen zwischen Ebenen unterliegen ebenfalls diesem Gesetz, es können jedoch detaillierte Durchführungsbestimmungen entsprechend den Unterschieden zwischen den Ebenen erlassen werden.</p><h2 id="ii-grundrechte-der-verbraucher" tabindex="-1">II. Grundrechte der Verbraucher <a class="header-anchor" href="#ii-grundrechte-der-verbraucher" aria-label="Permalink to &quot;II. Grundrechte der Verbraucher&quot;">​</a></h2><p>Dieses Gesetz legt fest, dass Verbraucher folgende neun Grundrechte genießen:</p><table tabindex="0"><thead><tr><th>Recht</th><th>Inhalt</th></tr></thead><tbody><tr><td>Recht auf Sicherheit</td><td>Der Verbraucher genießt beim Kauf, der Verwendung von Waren und dem Erhalt von Dienstleistungen das Recht, dass seine persönliche und Vermögenssicherheit nicht beeinträchtigt wird</td></tr><tr><td>Recht auf Wahrheitskenntnis</td><td>Der Verbraucher hat das Recht, die tatsächliche Situation der von ihm gekauften oder verwendeten Waren oder der erhaltenen Dienstleistungen zu kennen, einschließlich Inhaltsstoffe, Wirksamkeit, Risiken usw.</td></tr><tr><td>Recht auf autonome Wahl</td><td>Der Verbraucher hat das Recht, Waren oder Dienstleistungen autonom zu wählen, hat das Recht zu vergleichen, zu identifizieren und auszuwählen, und kann erzwungene Transaktionen ablehnen</td></tr><tr><td>Recht auf faire Transaktion</td><td>Der Verbraucher hat das Recht, faire Transaktionsbedingungen wie Qualitätsgarantie, angemessenen Preis, korrekte Messung usw. zu erhalten</td></tr><tr><td>Recht auf Entschädigung nach Gesetz</td><td>Der Verbraucher, der aufgrund des Kaufs, der Verwendung von Waren oder des Erhalts von Dienstleistungen persönliche oder Vermögensschäden erleidet, genießt das Recht, nach Gesetz Entschädigung zu erhalten</td></tr><tr><td>Recht auf Vereinsgründung zur Rechtswahrung</td><td>Der Verbraucher hat das Recht, nach Gesetz eine Verbraucherorganisation zu gründen oder ihr beizutreten, um seine eigenen legitimen Rechte und Interessen zu wahren</td></tr><tr><td>Recht auf Wissenserwerb</td><td>Der Verbraucher hat das Recht, Wissen und Informationen im Zusammenhang mit dem Konsum und dem Schutz der Verbraucherrechte und -interessen zu erhalten</td></tr><tr><td>Recht auf Respekt</td><td>Der Verbraucher genießt beim Kauf, der Verwendung von Waren und dem Erhalt von Dienstleistungen das Recht, dass seine persönliche Würde und ethnischen Bräuche respektiert werden</td></tr><tr><td>Recht auf Aufsicht</td><td>Der Verbraucher hat das Recht, Waren und Dienstleistungen sowie die Arbeit zum Schutz der Verbraucherrechte und -interessen zu beaufsichtigen und Kritik und Vorschläge zu äußern</td></tr></tbody></table><h2 id="iii-pflichten-der-unternehmer" tabindex="-1">III. Pflichten der Unternehmer <a class="header-anchor" href="#iii-pflichten-der-unternehmer" aria-label="Permalink to &quot;III. Pflichten der Unternehmer&quot;">​</a></h2><p>Unternehmer haben bei der Bereitstellung von Waren oder Dienstleistungen für Verbraucher folgende Pflichten zu erfüllen:</p><ol><li><strong>Pflicht zum geschäftlichen Handeln nach Gesetz</strong>: Der Unternehmer muss die Verfassung und die Gesetze befolgen und geschäftliche Aktivitäten innerhalb des genehmigten Geschäftsbereichs durchführen.</li><li><strong>Pflicht zur Sicherheitsgarantie</strong>: Der Unternehmer muss sicherstellen, dass die von ihm bereitgestellten Waren oder Dienstleistungen den Anforderungen der Garantie der persönlichen und Vermögenssicherheit entsprechen, und muss für Waren und Dienstleistungen, die die Sicherheit gefährden könnten, eine wahrheitsgemäße Erklärung und deutliche Warnung abgeben.</li><li><strong>Pflicht zur wahrheitsgemäßen Information</strong>: Der Unternehmer muss den Verbrauchern wahrheitsgemäße Informationen über Waren oder Dienstleistungen bereitstellen und darf keine falsche oder irreführende Werbung machen. Waren und Dienstleistungen der Kultivierungskategorie müssen die Grenzen der Wirksamkeit und potenzielle Risiken wahrheitsgemäß kennzeichnen.</li><li><strong>Pflicht zur Qualitätsgarantie</strong>: Der Unternehmer muss sicherstellen, dass unter normalen Bedingungen der Verwendung von Waren oder des Erhalts von Dienstleistungen die von ihm bereitgestellten Waren oder Dienstleistungen die Qualität, Leistung, Verwendung und Haltbarkeit aufweisen, die sie aufweisen sollten.</li><li><strong>Pflicht zur fairen Transaktion</strong>: Der Unternehmer darf nicht durch Standardklauseln, Mitteilungen, Erklärungen, Ladenankündigungen usw. Bestimmungen treffen, die für Verbraucher unfair und unangemessen sind, wie den Ausschluss oder die Einschränkung von Verbraucherrechten, die Verringerung oder Befreiung der Unternehmerverantwortung, die Erhöhung der Verbraucherantwort usw.</li><li><strong>Pflicht zum Kundendienst</strong>: Der Unternehmer muss entsprechend den staatlichen Bestimmungen oder der Vereinbarung mit dem Verbraucher die Verantwortung für Reparatur, Austausch, Rückgabe und andere Kundendienstpflichten übernehmen.</li><li><strong>Pflicht zum Datenschutz</strong>: Der Unternehmer muss die persönlichen Informationen und Bewusstseinsdaten des Verbrauchers schützen und darf diese ohne Zustimmung des Verbrauchers nicht sammeln, verwenden oder offenlegen.</li></ol><h2 id="iv-streitbeilegung-und-rechtliche-verantwortung" tabindex="-1">IV. Streitbeilegung und rechtliche Verantwortung <a class="header-anchor" href="#iv-streitbeilegung-und-rechtliche-verantwortung" aria-label="Permalink to &quot;IV. Streitbeilegung und rechtliche Verantwortung&quot;">​</a></h2><p>Wenn zwischen Verbrauchern und Unternehmern ein Streit über Verbraucherrechte und -interessen entsteht, kann dieser auf folgenden Wegen gelöst werden:</p><ul><li>Verhandlung und Vergleich mit dem Unternehmer</li><li>Anforderung der Vermittlung durch eine Verbraucherorganisation</li><li>Beschwerde bei der zuständigen Verwaltungsbehörde</li><li>Anforderung der Schiedsgerichtsbarkeit bei einer Schiedsstelle gemäß der mit dem Unternehmer erzielten Schiedsvereinbarung</li><li>Erhebung einer Klage beim Symbiose-Gericht</li></ul><p>Unternehmer, die gegen die Bestimmungen dieses Gesetzes verstoßen und die legitimen Rechte und Interessen der Verbraucher verletzen, tragen folgende Verantwortung:</p><table tabindex="0"><thead><tr><th>Rechtswidrige Aktivität</th><th>Rechtliche Verantwortung</th></tr></thead><tbody><tr><td>Bereitstellung mangelhafter Waren oder Dienstleistungen, die Schaden verursachen</td><td>Übernahme der Entschädigungsverantwortung, einschließlich medizinischer Kosten, Entschädigung für Arbeitsausfall, Entschädigung für Behinderung usw.</td></tr><tr><td>Betrügerische Aktivität</td><td>Erhöhung der Entschädigung gemäß der Anforderung des Verbrauchers, der Betrag beträgt das Dreifache des Preises der vom Verbraucher gekauften Waren oder der Kosten der erhaltenen Dienstleistungen</td></tr><tr><td>Falsche Werbung</td><td>Anordnung zur Einstellung der rechtswidrigen Aktivität, Beseitigung der Auswirkungen, Verhängung einer Geldbuße</td></tr><tr><td>Erzwungene Transaktion</td><td>Anordnung zur Korrektur, Rückerstattung unangemessener Gebühren, Verhängung einer Geldbuße</td></tr><tr><td>Verletzung der Privatsphäre des Verbrauchers</td><td>Übernahme der Entschädigung für moralischen Schaden, in schweren Fällen strafrechtliche Verfolgung</td></tr></tbody></table><h2 id="v-verbraucherorganisationen-und-soziale-aufsicht" tabindex="-1">V. Verbraucherorganisationen und soziale Aufsicht <a class="header-anchor" href="#v-verbraucherorganisationen-und-soziale-aufsicht" aria-label="Permalink to &quot;V. Verbraucherorganisationen und soziale Aufsicht&quot;">​</a></h2><p>Der Staat ermutigt und unterstützt alle Organisationen und Einzelpersonen, soziale Aufsicht über Aktivitäten durchzuführen, die die legitimen Rechte und Interessen der Verbraucher schädigen. Die Verbrauchervereinigung ist eine nach Gesetz gegründete soziale Organisation, die soziale Aufsicht über Waren und Dienstleistungen durchführt und die legitimen Rechte und Interessen der Verbraucher schützt, und erfüllt folgende Funktionen:</p><ol><li>Bereitstellung von Konsuminformationen und Beratungsdiensten für Verbraucher</li><li>Beteiligung an der Aufsicht und Prüfung von Waren und Dienstleistungen durch die zuständige Verwaltungsbehörde</li><li>Meldung, Anfrage und Unterbreitung von Vorschlägen an die zuständige Verwaltungsbehörde zu Fragen im Zusammenhang mit den legitimen Rechten und Interessen der Verbraucher</li><li>Entgegennahme von Beschwerden von Verbrauchern und Durchführung von Untersuchungen und Vermittlung zu den beschwerten Angelegenheiten</li><li>Unterstützung geschädigter Verbraucher bei der Erhebung von Klagen gegen Aktivitäten, die die legitimen Rechte und Interessen der Verbraucher schädigen</li></ol><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Verbraucherschutzgesetz》 ist der Wächter der Marktordnung der Anker-Symbiose-Zivilisation. Durch die Gewährung umfassender Rechte an Verbraucher, die Einschränkung des Verhaltens von Unternehmern und die Einrichtung eines vielfältigen Streitbeilegungsmechanismus stellt es sicher, dass Markttransaktionen auf dem Weg von Fairness, Integrität und Symbiose verlaufen, und verhindert, dass der Handelssektor zu einem neuen Nährboden für räuberisches Verhalten wird.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>41-共生劳动法 (Symbiose-Arbeitsgesetz)</li><li>47-反垄断法 (Antimonopolgesetz)</li><li>36-社会结构与阶层流动 (Sozialstruktur und Schichtenmobilität)</li></ul>',23)])])}const b=n(s,[["render",d]]);export{o as __pageData,b as default};
